  let startIndex = 0;
  if (cursor !== null) {
    const cursorIndex = items.findIndex(item => item.id === cursor);
    if (cursorIndex === -1) {
      throw new RangeError('unknown cursor');
    }
    startIndex = cursorIndex + 1;
  }

  // Extract the page
  const pageItems = items.slice(startIndex, startIndex + limit);
  const nextCursor = (startIndex + limit < items.length) ? items[startIndex + limit].id : null;

  return {
    items: pageItems,
    nextCursor
  };
}

